mapper.select:
SELECT * FROM crs_course
WHERE deleted = 0 AND status = 1

    AND (name LIKE CONCAT('%', #{query.keyword}, '%') 
         OR course_code LIKE CONCAT('%', #{query.keyword}, '%')
         OR teacher_name LIKE CONCAT('%', #{query.keyword}, '%'))


    AND semester = #{query.semester}


    AND category = #{query.category}


    AND department = #{query.department}


    AND teacher_id = #{query.teacherId}

ORDER BY course_code

SELECT * FROM crs_course
WHERE deleted = 0 AND status = 1

    AND semester = #{semester}

ORDER BY enrolled_count DESC
LIMIT #{limit}
